{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported result does not establish stability across runs."
        }
      ],
      "instrument_review": "MESA 14: Not sure whether repeated testing occurred. MESA 16: the supplied findings do not establish variation across runs."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly states that repeated testing did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "A single run establishes neither stability nor instability."
        }
      ],
      "instrument_review": "MESA 14: No, because repetition was explicitly absent. MESA 16: stability remains unresolved; absence of testing is not evidence of unstable scores."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes, repeated testing occurred. MESA 16: the observed range supports stability for this comparison under its stated definition."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing occurred regardless of whether its findings were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes, testing occurred. MESA 16: the reported variation directly conflicts with stability under the report's definition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation documentation supplies no evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no findings about variation across runs."
        }
      ],
      "instrument_review": "MESA 22: installation instructions help describe setup. They do not resolve MESA 14 or 16 concerning repeated testing and score variation."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2 and 25: the intended comparison fits the reported grid performance. MESA 9 and 20: evidence for broader abilities or performance is absent."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results support A's better performance on these evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "An intended use involving general intelligence does not supply evidence for that inference."
        }
      ],
      "instrument_review": "MESA 9, 20 and 25: the narrow findings do not support the intended selection for general intelligence across domains. The observed grid comparison remains supported."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone supply no demonstrated link to better real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial, blinded correctness checks and reported uncertainty interval support better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Better decision correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "MESA 20: the later trial adds evidence beyond initial test scores for workshop decision correctness. MESA 13, 16 and 25: the comparison and uncertainty support the stated local use, while safety claims remain unsupported."
    }
  ],
  "closing_note": "No instructions were unclear. Missing evidence was distinguished from explicit contradiction, and testing occurrence from favourable findings."
}
